begin;

-- ANGELCARE MARKETPLACE — ULTRA MEGA ZIP 2
-- Final production authority: workspace access, Academy remediation,
-- governed homepage releases, and canonical MZ2 workspace registry.
-- ADDITIVE / IDEMPOTENT. No production row is deleted or truncated.

create table if not exists public.angelcare_marketplace_workspace_access(
  id uuid primary key default gen_random_uuid(),
  app_user_id uuid not null references public.app_users(id) on delete restrict,
  workspace_key text not null,
  enabled boolean not null default true,
  territory_id uuid,
  tenant_id uuid,
  starts_at timestamptz,
  expires_at timestamptz,
  reason text,
  granted_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(app_user_id,workspace_key)
);
create index if not exists ac_marketplace_workspace_access_user_idx on public.angelcare_marketplace_workspace_access(app_user_id,enabled);
create index if not exists ac_marketplace_workspace_access_key_idx on public.angelcare_marketplace_workspace_access(workspace_key,enabled);

create table if not exists public.angelcare_marketplace_academy_remediations(
  id uuid primary key default gen_random_uuid(),
  public_reference text not null unique default ('ACREM-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),
  enrollment_id uuid not null references public.angelcare_marketplace_academy_enrollments(id) on delete restrict,
  assessment_result_id uuid references public.angelcare_marketplace_academy_assessment_results(id) on delete restrict,
  reason text not null,
  action_plan text not null,
  status text not null default 'open' check(status in('open','in_progress','evidence_review','completed','cancelled','reopened')),
  owner_id uuid,
  due_at timestamptz,
  completed_at timestamptz,
  evidence jsonb not null default '{}'::jsonb,
  territory_id uuid,
  tenant_id uuid references public.angelcare_marketplace_partner_tenants(id) on delete restrict,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists ac_marketplace_academy_remediation_status_idx on public.angelcare_marketplace_academy_remediations(status,due_at);
create index if not exists ac_marketplace_academy_remediation_enrollment_idx on public.angelcare_marketplace_academy_remediations(enrollment_id,status);

create table if not exists public.angelcare_marketplace_homepage_release_dossiers(
  id uuid primary key default gen_random_uuid(),
  public_reference text not null unique default ('HPREL-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),
  homepage_version_id uuid references public.angelcare_marketplace_homepage_versions(id) on delete restrict,
  locale text not null default 'fr' check(locale in('fr','en','ar')),
  territory_id uuid references public.angelcare_marketplace_territories(id) on delete restrict,
  status text not null default 'draft' check(status in('draft','content_ready','review','approval_pending','approved','scheduled','published','verification','accepted','rollback_required','rolled_back','superseded','archived','rejected')),
  release_title text not null,
  scope jsonb not null default '{}'::jsonb,
  readiness jsonb not null default '{}'::jsonb,
  preview_evidence jsonb not null default '{}'::jsonb,
  approval_evidence jsonb not null default '{}'::jsonb,
  publication_evidence jsonb not null default '{}'::jsonb,
  rollback_of_id uuid references public.angelcare_marketplace_homepage_release_dossiers(id) on delete restrict,
  owner_id uuid,
  approved_by uuid,
  approved_at timestamptz,
  scheduled_at timestamptz,
  published_at timestamptz,
  verified_at timestamptz,
  archived_at timestamptz,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists ac_marketplace_homepage_release_status_idx on public.angelcare_marketplace_homepage_release_dossiers(status,created_at desc);

