on conflict(workspace_key) do update set
  route=excluded.route,
  domain=excluded.domain,
  mission=excluded.mission,
  primary_entity_type=excluded.primary_entity_type,
  workspace_type=excluded.workspace_type,
  lifecycle=excluded.lifecycle,
  required_capabilities=excluded.required_capabilities,
  required_evidence=excluded.required_evidence,
  verticality_version=excluded.verticality_version,
  status='production',
  owner_role='marketplace_admin',
  updated_at=now();

-- Existing absolute Admin accounts are explicitly granted wildcard workspace authority.
insert into public.angelcare_marketplace_workspace_access(app_user_id,workspace_key,enabled,reason,granted_by)
select distinct a.app_user_id,'*',true,'Ultra MZ2 absolute Admin workspace authority',a.app_user_id
from public.angelcare_marketplace_user_role_assignments a
where a.active=true and a.role_key='marketplace_admin'
on conflict(app_user_id,workspace_key) do update set enabled=true,reason=excluded.reason,updated_at=now();

-- Safe RLS boundary: these tables are server-only authority stores.
alter table public.angelcare_marketplace_workspace_access enable row level security;
alter table public.angelcare_marketplace_academy_remediations enable row level security;
alter table public.angelcare_marketplace_homepage_release_dossiers enable row level security;
revoke all on table public.angelcare_marketplace_workspace_access,public.angelcare_marketplace_academy_remediations,public.angelcare_marketplace_homepage_release_dossiers from anon,authenticated;
grant all on table public.angelcare_marketplace_workspace_access,public.angelcare_marketplace_academy_remediations,public.angelcare_marketplace_homepage_release_dossiers to service_role;

commit;
